IR_ARJ  = "https://www.iranicaonline.org/articles/arjasp"
WP_JAM  = "https://en.wikipedia.org/wiki/Jamaspa"

nodes = []

nodes.append({
 "id": 6, "lang": "Avestan",
 "words": "aršan-aspa; aurvat-aspa; arejat-aspa; jâm-âspa",
 "verdict": "disputed",
 "derivation": "Two of the four are exactly right, one is unattested and one is glossed on a guess. aurvaṱ.aspa- is in Bartholomae as '• j. ʼaurvataspa- Adj. \"der schnelle Rosse hat\"', used of the sun (hvarə.xšaēta- ... aurvaṱ.aspəm, Yt.6.1) and as the name of Vīštāspa's father — Nourai's '(with) swift horses' is verbatim right. arəǰaṱ.aspa- is likewise in Bartholomae, '• j. arəǰaṱ.aspa- m. EN. eines Hyaona-Fürsten' (Yt.9.30, 5.109), from arəj- 'to be worth', so '(with) valuable horses' is the standard analysis (Iranica s.v. ARJĀSP). Jāmāspa- is a real Avestan name (Bartholomae s.v., with the patronymic Jāmāspana-), but the first element is admittedly obscure: proposals are Vedic kṣāmá- 'singed', Gershevitch's 'leading horses' and Schwartz's 'he who bridles horses'; 'owning horses' is nobody's. Finally *aršan-aspa- is not in Bartholomae at all: aršan- 'male, stallion' is well attested on its own, and compound names like auruša.aspa- 'having white horses' show the type, but this particular compound has to be reconstructed.",
 "derivation_fa": "دو نام از چهار نام دقیقاً درست است: aurvaṱ.aspa- را بارتولمه «دارندهٔ اسبان تندرو» معنی می‌کند (صفتِ خورشید در یشت ۶) و arəǰaṱ.aspa- نام سرکردهٔ خیونان است (یشت ۹/۳۰) از ریشهٔ arəj- «ارزیدن»، پس «دارندهٔ اسبان گران‌بها» درست است. امّا Jāmāspa- گرچه نامی اوستایی است، جزء نخست آن روشن نیست و پیشنهادها «سوخته» (قس. سنسکریت kṣāmá-)، «رهبری‌کنندهٔ اسبان» (گرشویچ) و «لگام‌زنندهٔ اسبان» (شوارتز) است؛ معنی «دارندهٔ اسب» پشتوانه‌ای ندارد. همچنین ترکیب *aršan-aspa- در فرهنگ بارتولمه نیامده است، هرچند aršan- «نر، نریان» به‌تنهایی گواهی شده و ترکیب‌هایی مانند auruša.aspa- «دارندهٔ اسبان سپید» این الگو را نشان می‌دهد.",
 "sources": [IR_ARJ, WP_JAM, IR_NAMES],
 "ref_check": [
